// কিতাব থেকে সরাসরি লেখা তামরীন (scripts/tamrin_book → node scripts/apply_tamrin_book.cjs)
// যে পর্বের কিতাব-তামরীন আছে, সেই পর্বের পুরনো (কিতাবের সাথে না মেলা) তামরীন বাদ যায়।
// প্রতিটি তামরীন ছোট ছোট নোডে ভাঙা — নোডের নম্বর "১.২" (তামরীন ১, অংশ ২)।
import bookData from './tamrinBook.json';

const bookTamrins = bookData.nodes;

const toBn = (n) => String(n).replace(/[0-9]/g, (d) => '০১২৩৪৫৬৭৮৯'[d]);
const bookNodesByPart = {};
bookTamrins.forEach((bt) => {
  const part = tamrinParts.find((p) => p.id === bt.partId);
  const numBn = toBn(bt.tamrinNumber) + (bt.subCount > 1 ? '.' + toBn(bt.subIndex) : '');
  (bookNodesByPart[bt.partId] = bookNodesByPart[bt.partId] || []).push({
    id: bt.id,
    partId: bt.partId,
    partKey: part?.partKey,
    partName: bookData.parts[bt.partId]?.name || part?.name,
    tamrinNumber: bt.tamrinNumber,
    tamrinNumberBn: numBn,
    subIndex: bt.subIndex || 1,
    title: 'তামরীন ' + numBn,
    arabicTitle: 'التَّمْرِينُ',
    page: bt.page,
    pagesStr: 'পৃষ্ঠা ' + bt.page,
    grammarFocus: 'কিতাবের অনুশীলন',
    summary: 'মূল কিতাবের পৃষ্ঠা ' + bt.page + '-এর তামরীন — আরবি থেকে বাংলা ও বাংলা থেকে আরবি।',
    exercises: bt.exercises
  });
});
Object.entries(bookNodesByPart).forEach(([partId, nodes]) => {
  const part = tamrinParts.find((p) => p.id === Number(partId));
  if (!part) return;
  const meta = bookData.parts[partId];
  if (meta) Object.assign(part, meta);
  part.tamrins = nodes;
  part.totalTamrins = nodes.length;
  const first = allTamrins.findIndex((t) => t.partId === Number(partId));
  const kept = allTamrins.filter((t) => t.partId !== Number(partId));
  const at = first < 0 ? kept.length : first;
  allTamrins.splice(0, allTamrins.length, ...kept.slice(0, at), ...nodes, ...kept.slice(at));
});

// কিতাবের শেষের "নতুন শব্দ" (اَلْكَلِمَاتُ الْجَدِيدَةُ, পৃষ্ঠা ২২৩ - ২৪৬) — তামরীনের সীমা ধরে শব্দ অনুশীলন।
// প্রতিটি তালিকা সর্বোচ্চ ১০টি শব্দের সেটে ভাগ করা; সেট খুললে আরবি→বাংলা ও বাংলা→আরবি প্রশ্ন হয়।
// তালিকাগুলো তামরীনের ধারার (আনলক শৃঙ্খলের) বাইরে, তাই আগের অগ্রগতি বদলায় না।
const WORD_SET_SIZE = 10;
export const tamrinWordGroups = (bookData.glossary || []).map((g) => {
  const rangeBn = g.from ? `তামরীন ${toBn(g.from)} - ${toBn(g.to)}` : null;
  const pagesStr = 'পৃষ্ঠা ' + toBn(g.pages[0]) + (g.pages.length > 1 ? ' - ' + toBn(g.pages[g.pages.length - 1]) : '');
  // সেটগুলো প্রায় সমান আকারের (যেমন ১১২টি শব্দ → ১২টি সেটে ৯-১০টি করে)
  const setCount = Math.max(1, Math.ceil(g.words.length / WORD_SET_SIZE));
  const base = Math.floor(g.words.length / setCount);
  const extra = g.words.length % setCount;
  const chunks = [];
  for (let k = 0, at = 0; k < setCount; k++) {
    const size = base + (k < extra ? 1 : 0);
    chunks.push(g.words.slice(at, at + size));
    at += size;
  }
  const group = {
    id: g.id,
    partId: g.partId,
    from: g.from,
    to: g.to,
    title: rangeBn ? `নতুন শব্দ: ${rangeBn}` : g.title,
    pagesStr,
    words: g.words
  };
  group.sets = chunks.map((words, k) => ({
    id: `${g.id}-s${k + 1}`,
    kind: 'words',
    groupId: g.id,
    partId: g.partId,
    setIndex: k + 1,
    setCount: chunks.length,
    tamrinNumberBn: `সেট ${toBn(k + 1)}`,
    title: `${group.title} • সেট ${toBn(k + 1)}/${toBn(chunks.length)}`,
    page: words[0].page,
    pagesStr,
    words,
    groupWords: g.words
  }));
  return group;
});

export const getTamrinWordGroups = (partId) => tamrinWordGroups.filter((g) => g.partId === partId);

// প্রতিটি পর্বের শেষ তামরীনের id (পরের পর্ব আনলকের শর্তে ব্যবহৃত)
export const getTamrinPartLastId = (partId) => {
  const part = tamrinParts.find((p) => p.id === partId);
  return part?.tamrins?.[part.tamrins.length - 1]?.id || null;
};

export default tamrinParts;
